import {zipFiles} from './kitchen-specs.js?v=binary-1';
import {requestPNG,requestText} from './markup-export.js';

const $=id=>document.getElementById(id),COLORS=['#fb6644','#00bfc9','#b87cff','#e8b528','#ed68bc'];
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function wrap(ctx,text,width){const lines=[];for(const paragraph of text.split('\n')){let line='';for(const word of paragraph.split(/\s+/)){if(ctx.measureText(line+word).width>width&&line){lines.push(line.trimEnd());line='';}for(const char of word+' '){if(ctx.measureText(line+char).width>width){lines.push(line);line='';}line+=char;}}lines.push(line.trimEnd());}return lines;}
function ellipse(a,b){return Array.from({length:65},(_,i)=>{const t=i/64*Math.PI*2;return [(a[0]+b[0])/2+Math.abs(b[0]-a[0])/2*Math.cos(t),(a[1]+b[1])/2+Math.abs(b[1]-a[1])/2*Math.sin(t)];});}
export function mountAreaMarkup({capture,release,toast}){
 const dialog=document.createElement('dialog');dialog.id='areaMarkup';dialog.setAttribute('aria-labelledby','markupTitle');
 dialog.innerHTML=`<div class="markupHeader"><div><span class="markupEyebrow">FINISH REQUEST</span><h2 id="markupTitle">Circle it. Try something new.</h2></div><button id="markupClose" aria-label="Close marking tool">Close</button></div>
 <div class="markupMobileTabs" role="group" aria-label="Request step"><button id="markupDrawStep" class="active" aria-pressed="true">1. Mark area</button><button id="markupDetailsStep" aria-pressed="false">2. Details &amp; save</button></div>
 <div class="markupBody"><section class="markupWorkspace"><div class="markupToolbar"><div role="group" aria-label="Drawing tool"><button id="markupEllipse" class="active" aria-pressed="true">Circle</button><button id="markupFreehand" aria-pressed="false">Freehand</button></div><button id="markupUndo" disabled>Undo</button><button id="markupClear" disabled>Clear</button></div><p id="markupInstruction">Drag a circle around the surface you want to change.</p><div id="markupStage"><canvas id="markupCanvas" tabindex="0" aria-label="Captured house view. Drag to circle an area."></canvas></div><p class="markupFrozen">View frozen · Save your request before closing to move around the house.</p><button id="markupNext" class="markupPrimary" disabled>Next: add note &amp; photo →</button></section>
 <section class="markupDetails" aria-label="Finish request details"><p class="markupStep">1 / YOUR AREA</p><div id="markupAreas"><p class="markupEmpty">Circle a tile, counter, cabinet, or any other area. You can mark more than one.</p></div><label>Area / location<input id="markupLocation" maxlength="160"></label><label>Apply the change to<select id="markupScope"><option value="circled-only">Only the circled area(s)</option><option value="matching-surface">That surface throughout this room</option></select></label>
 <p class="markupStep">2 / YOUR IDEA</p><label>What would you like to try?<textarea id="markupNote" rows="3" maxlength="2000" placeholder="Try this tile on the shower walls. Keep the floor as it is."></textarea></label><label class="markupUpload">+ Add a product photo <span>Optional · JPG, PNG or WebP · up to 15 MB</span><input id="markupReference" type="file" accept="image/jpeg,image/png,image/webp"></label><div id="markupReferencePreview" hidden><img id="markupReferenceImage" alt="Your product reference"><span id="markupReferenceName"></span><button id="markupRemoveReference" aria-label="Remove product photo">Remove</button></div>
 <div class="markupHandoff"><p class="markupStep">3 / BRING IT HERE</p><p>Save the marked image and drag it into our chat. Your note and product photo travel with it.</p><button id="markupSave" class="markupPrimary" disabled>Save marked image</button><div class="markupSecondary"><button id="markupCopy" disabled>Copy request text</button><button id="markupBundle" disabled>Full request (.zip)</button></div><p id="markupStatus" role="status" aria-live="polite">Room, surface and 3D location are included automatically.</p></div></section></div>`;
 document.body.append(dialog);
 const canvas=$('markupCanvas'),ctx=canvas.getContext('2d');
 let snapshot=null,areas=[],tool='ellipse',stroke=null,pointerId=null,reference=null,referenceURL=null,busy=false,requestId=null;
 const active=()=>dialog.open;
 function fit(){if(!snapshot)return;const r=$('markupStage').getBoundingClientRect(),scale=Math.min((r.width-12)/canvas.width,(r.height-12)/canvas.height);canvas.style.width=Math.max(1,canvas.width*scale)+'px';canvas.style.height=Math.max(1,canvas.height*scale)+'px';draw();}
 function trace(context,points,w,h){context.beginPath();points.forEach(([x,y],i)=>i?context.lineTo(x*w,y*h):context.moveTo(x*w,y*h));context.closePath();}
 function paint(context,w,h,live=true){const scale=w/Math.max(1,canvas.getBoundingClientRect().width),line=Math.min(8,Math.max(3,2.5*scale));for(const [i,a] of [...areas,...(live&&stroke?[{points:stroke}]:[])].entries()){const color=COLORS[i%COLORS.length];trace(context,a.points,w,h);context.fillStyle=color+'12';context.fill();context.strokeStyle='#ffffff';context.lineWidth=line+3;context.stroke();context.strokeStyle=color;context.lineWidth=line;context.stroke();if(a.id){const x=Math.max(18,Math.min(w-20,a.points[0][0]*w)),y=Math.max(18,Math.min(h-20,a.points[0][1]*h));context.fillStyle=color;context.beginPath();context.arc(x,y,line*3,0,Math.PI*2);context.fill();context.font=`bold ${line*3}px Arial`;context.fillStyle='#fff';context.textAlign='center';context.textBaseline='middle';context.fillText(String(i+1),x,y);context.textAlign='left';context.textBaseline='alphabetic';}}}
 function draw(){if(!snapshot)return;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(snapshot.image,0,0,canvas.width,canvas.height);paint(ctx,canvas.width,canvas.height);}
 function renderAreas(){
  const host=$('markupAreas');host.replaceChildren();
  if(!areas.length){const p=document.createElement('p');p.className='markupEmpty';p.textContent='Circle a tile, counter, cabinet, or any other area. You can mark more than one.';host.append(p);}
  for(const [i,a] of areas.entries()){const row=document.createElement('label');row.className='markupArea';const label=document.createElement('span');label.textContent=`${i+1}. Surface in this circle`;label.style.color=COLORS[i%COLORS.length];row.append(label);const select=document.createElement('select');select.setAttribute('aria-label',`Surface in circle ${i+1}`);for(const t of a.targets){const o=document.createElement('option');o.value=t.key;o.textContent=t.label;select.append(o);}const all=document.createElement('option');all.value='';all.textContent=a.targets.length?'Entire circled area':'Area marked · surface not identified';select.append(all);select.value=a.targetKey||'';select.onchange=()=>{a.targetKey=select.value;};row.append(select);host.append(row);}
  for(const id of ['markupSave','markupCopy','markupBundle','markupUndo','markupClear','markupNext'])$(id).disabled=!areas.length||busy;
  $('markupInstruction').textContent=areas.length?`${areas.length} area${areas.length===1?'':'s'} marked. Check the surface, then describe your idea.`:'Drag a circle around the surface you want to change.';
  draw();
 }
 function point(e){const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];}
 canvas.onpointerdown=e=>{if(e.button!==0||busy||pointerId!==null)return;e.preventDefault();pointerId=e.pointerId;canvas.setPointerCapture(pointerId);stroke=[point(e)];};
 let startPoint;
 canvas.addEventListener('pointerdown',e=>{if(e.pointerId===pointerId)startPoint=point(e);});
 canvas.onpointermove=e=>{if(e.pointerId!==pointerId)return;const p=point(e);if(tool==='ellipse')stroke=ellipse(startPoint,p);else if(stroke.length<3000)stroke.push(p);draw();};
 canvas.onpointerup=e=>{
  if(e.pointerId!==pointerId)return;pointerId=null;
  const points=stroke;stroke=null;const samples=points||[],xs=samples.map(p=>p[0]),ys=samples.map(p=>p[1]),r=canvas.getBoundingClientRect();
  if(samples.length<3||(Math.max(...xs)-Math.min(...xs))*r.width<8||(Math.max(...ys)-Math.min(...ys))*r.height<8){draw();$('markupStatus').textContent='Drag around an area to make a circle.';return;}
  if(areas.length>=8){draw();$('markupStatus').textContent='Up to 8 areas per request. Save this request, then start another.';return;}
  const targets=snapshot.pick(points);areas.push({id:'area-'+(areas.length+1),points,targets,targetKey:targets[0]?.key||''});$('markupStatus').textContent='Check the detected surface. Choose another in the list if needed.';renderAreas();
 };
 canvas.onpointercancel=canvas.onlostpointercapture=()=>{pointerId=null;stroke=null;draw();};
 for(const [id,value] of [['markupEllipse','ellipse'],['markupFreehand','freehand']])$(id).onclick=()=>{tool=value;for(const [bid,v] of [['markupEllipse','ellipse'],['markupFreehand','freehand']]){$(bid).classList.toggle('active',v===tool);$(bid).setAttribute('aria-pressed',String(v===tool));}};
 $('markupUndo').onclick=()=>{areas.pop();renderAreas();};$('markupClear').onclick=()=>{areas=[];renderAreas();};
 function step(value){dialog.dataset.step=value;for(const [id,v] of [['markupDrawStep','draw'],['markupDetailsStep','details']]){$(id).classList.toggle('active',v===value);$(id).setAttribute('aria-pressed',String(v===value));}if(value==='draw')fit();}
 $('markupDrawStep').onclick=()=>step('draw');$('markupDetailsStep').onclick=$('markupNext').onclick=()=>step('details');
 function removeReference(){reference=null;if(referenceURL)URL.revokeObjectURL(referenceURL);referenceURL=null;$('markupReference').value='';$('markupReferencePreview').hidden=true;}
 $('markupRemoveReference').onclick=removeReference;
 $('markupReference').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15*1024*1024){$('markupStatus').textContent='Choose a JPG, PNG or WebP image smaller than 15 MB.';e.target.value='';return;}const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();removeReference();referenceURL=url;reference={file,image:img};$('markupReferenceImage').src=url;$('markupReferenceName').textContent=file.name;$('markupReferencePreview').hidden=false;$('markupStatus').textContent='Product photo added. It will appear beside your note in the saved image.';}catch{URL.revokeObjectURL(url);$('markupStatus').textContent='That image could not be opened. Try a JPG or PNG.';}};
 function request(){return {schema:'house3d-area-request/v1',id:requestId,createdAt:new Date().toISOString(),context:snapshot.context,location:$('markupLocation').value.trim(),note:$('markupNote').value.trim(),scope:$('markupScope').value,areas:areas.map(a=>({id:a.id,outline:a.points.map(p=>p.map(v=>Math.round(v*1e6)/1e6)),selectedTarget:a.targets.find(t=>t.key===a.targetKey)||null,candidates:a.targets})),reference:reference?{originalName:reference.file.name,bundleFile:'product-reference.'+({ 'image/png':'png','image/jpeg':'jpg','image/webp':'webp'}[reference.file.type]),type:reference.file.type}:null};}
 async function exportImage(data,reference){
  const out=document.createElement('canvas');out.width=Math.max(1100,Math.min(1920,canvas.width));const c=out.getContext('2d'),imageHeight=Math.round(canvas.height*out.width/canvas.width),pad=38,refWidth=reference?Math.round(out.width*.3):0,textWidth=out.width-pad*2-(refWidth?refWidth+35:0),font=24;
  c.font=font+'px Arial';const paragraphs=[data.context.floorLabel+' · '+data.location,...data.areas.map((a,i)=>`${i+1}. ${a.selectedTarget?.label||'Entire circled area'}${a.selectedTarget?.entityId?' ['+a.selectedTarget.entityId+']':''}`),data.note||'Use the product reference for the circled area.',data.scope==='matching-surface'?'Apply to this surface throughout the room.':'Apply only to the circled area(s).'];
  const lines=paragraphs.flatMap(t=>[...wrap(c,t,textWidth),'']);const footer=Math.max(250,115+lines.length*32,reference?430:0);out.height=imageHeight+footer;c.fillStyle='#14272c';c.fillRect(0,0,out.width,out.height);c.drawImage(snapshot.image,0,0,out.width,imageHeight);paint(c,out.width,imageHeight,false);
  c.fillStyle='#a9d5c5';c.font='bold 22px Arial';c.fillText('BRINES HOUSE / '+data.id,pad,imageHeight+43);c.fillStyle='#fff';c.font=font+'px Arial';lines.forEach((line,i)=>c.fillText(line,pad,imageHeight+85+i*32));
  c.fillStyle='#9fbbbf';c.font='18px Arial';c.fillText('Marked request · '+data.context.designName+' · Exact 3D details embedded in this PNG',pad,out.height-24);
  if(reference){const x=out.width-pad-refWidth,y=imageHeight+75;c.fillStyle='#a9d5c5';c.font='bold 19px Arial';c.fillText('PRODUCT REFERENCE',x,imageHeight+43);const scale=Math.min(refWidth/reference.image.width,280/reference.image.height),w=reference.image.width*scale,h=reference.image.height*scale;c.drawImage(reference.image,x,y,w,h);c.font='18px Arial';c.fillStyle='#d1e0e1';wrap(c,reference.file.name,refWidth).slice(0,2).forEach((line,i)=>c.fillText(line,x,y+h+28+i*23));}
  const blob=await new Promise(resolve=>out.toBlob(resolve,'image/png'));if(!blob)throw Error('Could not save the image.');return requestPNG(new Uint8Array(await blob.arrayBuffer()),data);
 }
 async function save(bundle){if(busy||!areas.length)return;busy=true;renderAreas();$('markupStatus').textContent='Preparing your marked image…';try{const data=request(),product=reference,png=await exportImage(data,product),base='brines-'+data.context.floor+'-'+data.id.toLowerCase();if(bundle){const files={'marked-view.png':png,'request.json':JSON.stringify(data,null,2),'request.txt':requestText(data)};if(product)files[data.reference.bundleFile]=new Uint8Array(await product.file.arrayBuffer());download(zipFiles(files),base+'.zip','application/zip');}else download(png,base+'.png','image/png');$('markupStatus').textContent='Saved. Drag the downloaded '+(bundle?'ZIP':'PNG')+' into our chat and I can work from your marked area.';}catch(e){$('markupStatus').textContent='Could not save: '+e.message;}finally{busy=false;renderAreas();}}
 $('markupSave').onclick=()=>save(false);$('markupBundle').onclick=()=>save(true);
 $('markupCopy').onclick=async()=>{try{await navigator.clipboard.writeText(requestText(request()));$('markupStatus').textContent='Request text copied. Paste it in our chat with the marked image.';}catch{$('markupStatus').textContent='Clipboard unavailable. Save the image or full request instead.';}};
 $('markupClose').onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});dialog.addEventListener('close',()=>{pointerId=null;stroke=null;release();});
 new ResizeObserver(fit).observe($('markupStage'));
 return {get active(){return active();},open(){if(active())return;try{snapshot=capture();if(!snapshot)return;areas=[];stroke=null;removeReference();requestId='AREA-'+new Date().toISOString().replace(/[-:TZ.]/g,'').slice(0,14)+'-'+crypto.randomUUID().slice(0,4).toUpperCase();canvas.width=snapshot.image.width;canvas.height=snapshot.image.height;$('markupLocation').value=snapshot.context.viewRoom;$('markupNote').value='';$('markupScope').value='circled-only';$('markupStatus').textContent='Room, surface and 3D location are included automatically.';dialog.showModal();step('draw');renderAreas();fit();}catch(e){release();toast('Could not open the marking tool: '+e.message);}}};
}
